package com.haitong.files;

import com.haitong.config.RelayProperties;
import com.haitong.core.*;
import java.io.*;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.zip.*;
import jakarta.annotation.PreDestroy;
import org.springframework.beans.factory.InitializingBean;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.stereotype.Component;

/** Single-node, persistent local storage. Every disk name is generated by the server. */
@Component
@ConditionalOnProperty(prefix="relay.files",name="enabled",havingValue="true")
public class FileStorage implements InitializingBean {
    public record Saved(Path path,String sha256,long size) {}
    private final RelayProperties relay;private final FileTransferProperties p;private final Path root;
    private final Semaphore streams;private FileChannel lockChannel;private FileLock lock;
    public FileStorage(RelayProperties relay,FileTransferProperties p){this.relay=relay;this.p=p;root=Path.of(relay.getWorkDir()).toAbsolutePath().normalize().resolve("unstructured");streams=new Semaphore(p.getMaxStreams());}
    @Override public void afterPropertiesSet() throws IOException {
        Files.createDirectories(root);if(Files.isSymbolicLink(root))throw new IOException("文件存储目录不可为符号链接");
        lockChannel=FileChannel.open(root.resolve(".node.lock"),StandardOpenOption.CREATE,StandardOpenOption.WRITE);lock=lockChannel.tryLock();
        if(lock==null)throw new IllegalStateException("文件存储目录已被另一实例使用；本地文件模式仅支持单节点");
    }
    public Path directory(String id) throws IOException {
        UUID.fromString(id);Path path=root.resolve(id);Files.createDirectories(path);
        if(Files.isSymbolicLink(path)||!path.toRealPath().startsWith(root.toRealPath()))throw new IOException("存储路径非法");return path;
    }
    public Path checked(String value) throws IOException {
        Path path=Path.of(value).toAbsolutePath().normalize();
        if(!path.startsWith(root)||!path.toRealPath().startsWith(root.toRealPath())||Files.isSymbolicLink(path))throw new IOException("文件引用非法");return path;
    }
    public void acquire(){if(!streams.tryAcquire())throw RelayException.capacity();}public void release(){streams.release();}
    public void freeSpace() throws IOException {if(Files.getFileStore(root).getUsableSpace()<relay.getLimits().getMinFreeDiskBytes())throw RelayException.capacity();}
    public Saved save(String id,int no,String token,InputStream input,long expected,Runnable heartbeat) throws IOException {
        Path temp=directory(id).resolve("part-"+no+"-"+token);MessageDigest digest=digest();long count=0,last=System.nanoTime();
        try(FileChannel out=FileChannel.open(temp,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE)){
            byte[] buffer=new byte[65536];int n;
            while((n=input.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();if(n==0)continue;count+=n;if(count>expected)throw new RelayException(413,"PART_TOO_LARGE","分片字节数超过约定长度");
                digest.update(buffer,0,n);ByteBuffer bytes=ByteBuffer.wrap(buffer,0,n);while(bytes.hasRemaining())out.write(bytes);
                if(System.nanoTime()-last>TimeUnit.SECONDS.toNanos(10)){heartbeat.run();freeSpace();last=System.nanoTime();}
            }
            if(count!=expected)throw RelayException.invalid("分片字节数与约定长度不一致");out.force(true);
        }catch(Exception e){Files.deleteIfExists(temp);throw e;}
        PayloadFiles.syncDirectory(temp.getParent());return new Saved(temp,HexFormat.of().formatHex(digest.digest()),count);
    }
    public Saved assemble(FileUploadRepository.Upload u,List<Map<String,Object>> parts,Runnable heartbeat) throws IOException {
        Path temp=directory(u.id()).resolve("assembled-"+u.text("lease_token"));MessageDigest digest=digest();long count=0,last=System.nanoTime();
        try(FileChannel out=FileChannel.open(temp,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE)){
            byte[] buffer=new byte[65536];
            for(var part:parts){MessageDigest partDigest=digest();long partBytes=0;
                try(InputStream in=Files.newInputStream(checked(part.get("payload_path").toString()))){int n;
                    while((n=in.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();if(n==0)continue;count+=n;partBytes+=n;if(count>u.size())throw RelayException.invalid("文件分片总长不正确");digest.update(buffer,0,n);partDigest.update(buffer,0,n);
                        ByteBuffer bytes=ByteBuffer.wrap(buffer,0,n);while(bytes.hasRemaining())out.write(bytes);
                        if(System.nanoTime()-last>TimeUnit.SECONDS.toNanos(10)){heartbeat.run();freeSpace();last=System.nanoTime();}
                    }
                }
                if(partBytes!=((Number)part.get("size_bytes")).longValue()||!HexFormat.of().formatHex(partDigest.digest()).equals(part.get("sha256")))throw RelayException.invalid("已确认分片的磁盘内容校验失败");
            }
            if(count!=u.size())throw RelayException.invalid("文件总长度不正确");out.force(true);
        }catch(Exception e){Files.deleteIfExists(temp);throw e;}
        String hash=HexFormat.of().formatHex(digest.digest());
        if(!u.text("expected_sha256").isEmpty()&&!hash.equals(u.text("expected_sha256"))){Files.deleteIfExists(temp);throw RelayException.invalid("整文件 SHA-256 不匹配");}
        try{verifyType(temp,u.text("file_name"));}catch(Exception e){Files.deleteIfExists(temp);throw e;}
        PayloadFiles.syncDirectory(temp.getParent());return new Saved(temp,hash,count);
    }
    public String scan(Path file,boolean required,Runnable heartbeat) throws Exception {
        if(!required)return "HEADER_VERIFIED_NOT_SCANNED";
        List<String> args=p.getScannerCommand().stream().map(s->s.equals("{file}")?file.toString():s).toList();
        Process process=new ProcessBuilder(args).redirectOutput(ProcessBuilder.Redirect.DISCARD).redirectError(ProcessBuilder.Redirect.DISCARD).start();
        long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(p.getScannerTimeoutSeconds());
        try{
            while(!process.waitFor(5,TimeUnit.SECONDS)){heartbeat.run();if(System.nanoTime()>deadline)throw new IOException("恶意文件检查超时");}
            if(process.exitValue()!=0)throw new RelayException(422,"MALWARE_SCAN_REJECTED","文件未通过恶意文件检查");return "SCANNER_PASSED";
        }finally{if(process.isAlive())process.destroyForcibly();}
    }
    public void delete(String value) throws IOException {if(value!=null&&!value.isEmpty())Files.deleteIfExists(checked(value));}
    /** Never follows links, and never traverses outside this upload's UUID directory. */
    public void cleanup(String id,String keep) throws IOException {
        cleanupExcept(id,Set.of(keep));
    }
    public void cleanupExcept(String id,Set<String> keep) throws IOException {
        Path dir=directory(id);try(var entries=Files.newDirectoryStream(dir)){
            for(Path path:entries){if(keep.contains(path.toString()))continue;if(Files.isSymbolicLink(path)||!Files.isRegularFile(path,LinkOption.NOFOLLOW_LINKS))throw new IOException("上传目录包含异常对象");Files.delete(path);}
        }
        if(keep.isEmpty()||keep.equals(Set.of("")))Files.deleteIfExists(dir);
    }
    private static MessageDigest digest(){try{return MessageDigest.getInstance("SHA-256");}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
    private void verifyType(Path path,String name) throws IOException {
        byte[] header;try(InputStream in=Files.newInputStream(path)){header=in.readNBytes(16);}
        String ext=Rules.extension(name).substring(1).toLowerCase(Locale.ROOT);
        boolean okay=switch(ext){case "jpg","jpeg"->header.length>=3&&(header[0]&255)==255&&(header[1]&255)==216&&(header[2]&255)==255;
            case "png"->header.length>=8&&Arrays.equals(Arrays.copyOf(header,8),new byte[]{(byte)137,80,78,71,13,10,26,10});
            case "pdf"->header.length>=5&&new String(header,0,5,java.nio.charset.StandardCharsets.US_ASCII).equals("%PDF-");
            case "docx"->docx(path);default->false;};
        if(!okay)throw new RelayException(422,"FILE_TYPE_MISMATCH","文件内容与允许的格式不匹配");
    }
    private boolean docx(Path path) throws IOException {
        // Read the local ZIP stream instead of loading a possibly huge central directory into heap.
        boolean types=false,document=false;int entries=0;long expanded=0,compressed=Files.size(path);byte[] buffer=new byte[65536];
        try(ZipInputStream zip=new ZipInputStream(Files.newInputStream(path))){ZipEntry entry;
            while((entry=zip.getNextEntry())!=null){if(++entries>10000)return false;String name=entry.getName();
                if(name.startsWith("/")||name.contains("..")||name.contains("\\")||name.toLowerCase(Locale.ROOT).contains("vbaproject"))return false;
                types|=name.equals("[Content_Types].xml");document|=name.equals("word/document.xml");
                int n;while((n=zip.read(buffer))!=-1){expanded+=n;if(expanded>256L*1024*1024||expanded>Math.max(1024*1024,compressed*100))return false;}
            }
        }return types&&document;
    }
    @PreDestroy public void close() throws IOException {if(lock!=null)lock.release();if(lockChannel!=null)lockChannel.close();}
}
